def walk(p):
    out = []
    for name in repo.list(p):
        full = p + "/" + name if p != "." else name
        if name.endswith("/"):
            out = out + walk(full[:-1])
        else:
            out.append(full)
    return out

files = walk("src")
info = {}
for f in files:
    c = repo.read(f)
    info[f] = {"len": len(c), "occurrences": c.count("slow_path"), "repr_head": c[:80]}
return {"files": files, "info": info}

